'use strict';
const previousHome=home,previousRoutes=routes,previousCities=cities,previousEventPanel=eventPanel;
date=function(){return new Date(Date.UTC(2026,0,1+s.day)).toLocaleDateString('nb-NO',{weekday:'short',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});};
eventPanel=function(){return previousEventPanel()+(s.trip?`<section class="trip-pending"><span class="section-kicker">TUR / RETUR · ${G.ORIGINS[s.trip.origin].name}</span><h2>Du er på reise.</h2><p>${s.trip.remaining} dager gjenstår. Den nye lasten er ikke tilgjengelig før du er hjemme.</p>${btn('continueTrip','','Fortsett reisen →',!!s.event,'button brass')}</section>`:'');};
function depot(){const held=s.stock.reduce((a,n)=>a+n,0),stored=s.stash.reduce((a,n)=>a+n,0),next=G.LEVELS[s.rankLevel+1];return `<section class="depot"><div class="between"><div><span class="section-kicker">KOFFERT OG HJEMMELAGER / FAKTISKE VARER</span><h2>Kapitalen din ligger her.</h2><p>${held.toLocaleString('nb-NO')} enheter med deg · ${stored.toLocaleString('nb-NO')} på lager. Formue uten gjeld: ${kr(G.netWorth(s))}.</p></div><button class="button ghost" id="finance">Gjeld og advokat ↗</button></div>${next?`<div class="rank-next"><span>Neste rang: ${next.name} · ${kr(next.worth)}${s.rankLevel===4?' i produktiv imperieverdi + nettverksmål i Maktrådet':''}</span>${meter((s.rankLevel===4?G.empireValue(s):G.netWorth(s))/next.worth*100)}</div>`:''}<div class="inventory-grid">${G.GOODS.map((g,i)=>{const unlocked=G.unlocked(s,i);return `<article class="inventory-item ${unlocked?'':'locked'}"><span>${['◈','▥','▣','◷','✦','◇','❋','△','▱','◊'][i]}</span><b>${g.name}</b><strong>${s.stock[i].toLocaleString('nb-NO')}</strong><small>${s.stash[i]?'Lager '+s.stash[i].toLocaleString('nb-NO'):unlocked?'Tilgjengelig':'Låst av rang'}</small>${s.stock[i]?`<button class="text-button" data-store="${i}" data-direction="stash">Legg på lager ↓</button>`:s.stash[i]?`<button class="text-button" data-store="${i}" data-direction="case">Ta ut fra lager ↑</button>`:''}</article>`;}).join('')}</div>${s.lastTrade?tradeReport():''}<div class="market-actions"><button class="button brass" id="buyAbroad">Kjøp i utlandet ↗</button><button class="button brass" id="sellStreet" ${!held?'disabled':''}>Selg i Stavanger →</button>${btn('waitDay','','Vent én dag · −2 søkelys',s.ended||!!s.trip,'button ghost')}</div></section>`;}
function tradeReport(){const t=s.lastTrade;return t.kind==='trip'?`<div class="trade-result ${t.caught?'bad':''}"><b>${t.caught?'TOLLBESLAG':'HJEMME FRA '+G.ORIGINS[t.origin].name.toUpperCase()}</b><p>Varekjøp ${kr(t.value)} · tollrisiko ${pct(t.risk)}${t.caught?' · bot '+kr(t.fine):' · varene er lagt i kofferten'}. Reise og faste utgifter står i regnskapet.</p></div>`:`<div class="trade-result"><b>SALG GJENNOMFØRT</b><p>Brutto ${kr(t.gross)} − varekostnad ${kr(t.basis)} = ${kr(t.profit)} i varefortjeneste, før reise og drift. Salgsarbeid: ${t.days} dager.</p></div>`;}
home=function(){return previousHome().replace(/<div class="scene-buttons">[\s\S]*?<\/div>/,`<div class="scene-buttons"><button class="button brass" id="buyAbroadHero">Kjøp i utlandet ↗</button><button class="button glass" id="sellStreetHero" ${!s.stock.some(n=>n)?'disabled':''}>Selg i Stavanger →</button></div>`).replace(/<div class="phone-message">[\s\S]*?<\/div>/,`<div class="phone-message">«${G.canDelegate(s)?'Folkå tar vareflyten. Du må ta de store valgene. Ikkje glem kem som stille opp.':'Reis ut. Kjøp et parti. Få det hjem. Det som ser billig ud der ute, e ikkje penger før du har solgt det her.'}»</div>`).replace('Innkjøp og salg går av seg selv. Fire eller tretten uker passerer fram til ei viktig avgjørelse, høyt søkelys eller lite penger.',G.canDelegate(s)?'Innkjøp og salg kan delegeres. Tiden stopper ved viktige valg.':'Reiser og salg bruker dager. Ukentlig drift løper videre, og varer binder kapital mens du venter. Salgsapparatet bygger du opp senere.').replace('<section class="street-strip">',depot()+'<section class="street-strip">');};
function dealerPanel(){const enabled=G.canDelegate(s),quotes=G.GOODS.map((g,i)=>G.saleQuote(s,i,s.stock[i]+s.stash[i],true)),gross=quotes.reduce((n,q)=>n+q.gross,0),fee=quotes.reduce((n,q)=>n+q.commission,0),basis=quotes.reduce((n,q)=>n+q.basis,0);return `<section class="sales-network"><span class="section-kicker">FRA VAREHANDLER TIL BAKMANN</span><h2>Folkene selger. Du bygger videre.</h2><p>${enabled?'Salgsapparatet selger hele beholdningen i koffert og hjemmelager ved ukesoppgjøret. Ingen fast månedlig omsetningsgrense. Flere ledere og markeder forbedrer prisene og reduserer provisjonen.':'Automatisering åpner som Pusher ved 250 000 kr i opptjent formue, og krever én driftsleder. Før det skaffer og selger du faktiske partier selv.'}</p><div class="quote-mini"><span>Hele lageret, brutto nå <b>${kr(gross)}</b></span><span>Selgernes provisjon <b>${debit(fee)}</b></span><span>Historisk varekostnad <b>${debit(basis)}</b></span><span>Varefortjeneste før reise og fast drift <b>${kr(gross-fee-basis)}</b></span></div>${btn('autoSell','',s.autoSell?'Salgsapparat aktivt ✓':'Aktiver salgsapparatet',!enabled,'button brass')}<p class="small">Overskudd selges automatisk til fallende pris etter hvor mye markedet er overforsynt. Hele mengden omsettes; se faktisk brutto og varefortjeneste over. Ingen skjult kontantgrense. Provisjon: ${pct(Math.max(.06,.14-s.managers*.008))}.</p></section>`;}
routes=function(){return dealerPanel()+(G.canDelegate(s)||s.routes.length?previousRoutes():`<section class="empty-state"><h2>Driftsavtaler er en milepæl.</h2><p>En fast avtale skal erstatte en forsyningskjede du allerede kjenner: utenlandsk leverandør, innkjøp, transport, toll og salg i et valgt marked. Du får ikke automatisk gratis avanse fra første dag.</p><button class="button brass" id="buyAbroad">Finn ditt neste parti ↗</button></section>`);};
cities=function(){return previousCities()+`<h2 class="section-heading">Produksjon som fyller lageret.</h2><p>Produksjon betaler varekostnad og drift, og gir varer til lager. Lederne tilpasser normalt produksjonen til nettverkets etterspørsel. Full kapasitet kan velges, men overskuddspartier får fallende pris.</p><div class="market-actions">${btn('productionPolicy','demand',s.productionMode!=='volume'?'Markedstilpasset ✓':'Tilpass til markedet',false,'button ghost')}${btn('productionPolicy','volume',s.productionMode==='volume'?'Full kapasitet ✓':'Kjør full kapasitet',false,'button ghost')}</div><div class="production-grid">${G.FACTORIES.map((f,i)=>{const level=s.factories[i]?.level||0,production=G.productionQuote(s,i),cost=G.factoryCost(s,i);return `<article class="business"><span class="section-kicker">${G.LEVELS[f.level].name} / NIVÅ ${level}</span><h3>${f.name}</h3><p>${level?G.factoryCapacity(s,i).toLocaleString('nb-NO')+' enheter '+G.GOODS[f.good].name+' / uke':'Fyller lageret med '+G.GOODS[f.good].name}</p><p>${level?'Neste oppgjør: '+production.qty+' enheter · varekostnad og drift '+kr(production.cost):'Varekostnad følger leverandørpris; fast drift '+kr(f.fee)+' / uke'}. Stoppes ved manglende driftskapital.</p>${btn('factory',i,(level?'Utvid · ':'Etabler · ')+kr(cost),s.rankLevel<f.level||s.cash<cost,'button ghost')}</article>`;}).join('')}</div>`;};
function tripCalendarNotice(origin){const info=G.tripCalendar(s,origin),format=day=>new Date(Date.UTC(2026,0,1+day)).toLocaleDateString('nb-NO',{day:'numeric',month:'long',timeZone:'UTC'});return `<section class="travel-calendar"><b>Tilbake i Stavanger ${format(info.arrival)}</b>${info.events.length?`<p>Tar du reisen nå, er du bortreist under:</p><ul>${info.events.map(e=>`<li><b>${e.name}</b> · ${format(e.from)}–${format(e.to)} · ${e.entire?'du går glipp av hele perioden':'du går glipp av deler av perioden'}</li>`).join('')}</ul><p>Reisen forkortes ikke for å rekke en hendelse. Faste driftsavtaler og et aktivt salgsapparat jobber videre mens du er borte.</p>`:'<p>Ingen lokale kalenderhendelser overlapper reisen.</p>'}</section>`;}
function countries(){modal(`<span class="section-kicker">INNKJØP / VELG UTENLANDSTUR</span><h2>Billig ute. Kapital bundet hjemme.</h2><p>Hver tur er tur/retur fra Stavanger. Pris, tid, vareutvalg og tollrisiko teller. Varene må komme hjem før du kan selge dem.</p><div class="country-grid">${G.ORIGINS.map((o,i)=>`<button class="country-card" data-country="${i}" ${s.rankLevel<o.level||s.trip?'disabled':''}><span class="section-kicker">${o.place}</span><strong>${o.name}</strong><span>${o.days} dager · ${kr(G.travelCost(s,i))}</span><small>${s.rankLevel<o.level?'Krever '+G.LEVELS[o.level].name:Object.keys(o.goods).filter(g=>G.unlocked(s,+g)).map(g=>G.GOODS[g].name).join(' · ')}</small></button>`).join('')}</div><p class="small">Det finnes ingen månedlig gratiskvote gjennom tollen. Se lasten og kalenderen før du bestiller.</p>`);}
function purchase(origin){const o=G.ORIGINS[origin],ids=Object.keys(o.goods).map(Number).filter(i=>G.unlocked(s,i));modal(`<span class="section-kicker">STAVANGER → ${o.place} → STAVANGER</span><h2>Et parti fra ${o.name}.</h2><p>Tur/retur ${o.days} dager, ${kr(G.travelCost(s,origin))}. Du kjøper beholdning; dette gir ingen salgsinntekt ennå.</p><form id="purchaseForm"><div class="purchase-rows">${ids.map(i=>`<label><span><b>${G.GOODS[i].name}</b><small>${kr(G.sourcePrice(s,origin,i))} per enhet</small></span><input type="number" min="0" max="1000000" step="1" value="0" id="buyQ${i}" aria-label="Kjøp ${G.GOODS[i].name}"></label>`).join('')}</div><div id="purchaseQuote" class="planner-quote"></div><button class="button brass" type="submit">Reis, kjøp og frakt hjem →</button></form>`);const read=()=>G.GOODS.map((g,i)=>ids.includes(i)?+$('#buyQ'+i).value:0);function draw(){const cart=read(),value=cart.reduce((n,q,i)=>n+q*(G.sourcePrice(s,origin,i)||0),0);$('#purchaseQuote').innerHTML=`<div class="between"><span>Varekjøp</span><b>${kr(value)}</b></div><div class="between"><span>Tur/retur</span><b>${kr(G.travelCost(s,origin))} / ${o.days} dager</b></div><div class="between estimate"><span>Trekkes før avreise</span><b>${kr(value+G.travelCost(s,origin))}</b></div><div class="between"><span>Tollrisiko ved dagens søkelys</span><b>${pct(G.customs(s,value,origin))}</b></div><p class="small">${s.cash<value+G.travelCost(s,origin)?'Du har ikke nok penger. ':''}Større last og gjentatte turer øker risikoen. Ukentlig drift løper mens du reiser. Ved beslag mister du den nye lasten og kan få bot.</p>${tripCalendarNotice(origin)}`;$('#purchaseForm button[type="submit"]').textContent=G.tripCalendar(s,origin).events.length?'Reis likevel – full reisetid':'Reis, kjøp og frakt hjem →';}ids.forEach(i=>$('#buyQ'+i).oninput=draw);draw();$('#purchaseForm').onsubmit=e=>{e.preventDefault();const before=s.trips;const message=act('tripBuy',{origin,cart:read()});if(s.trips>before||s.trip)$('#dialog').close();};}
function sellMarket(){if(s.trip)return toast('Du må hjem først.');const ids=s.stock.map((n,i)=>n?i:-1).filter(i=>i>=0);if(!ids.length)return toast('Kofferten er tom. Kjøp i utlandet eller hent varer fra hjemmelageret.');const market=G.market(s,ids[0]);modal(`<span class="section-kicker">HJEMMEMARKED / ${market.area} / ${date()}</span><h2>Selg det du faktisk har.</h2><p>Pris og etterspørsel er låst for dagen. Et salg bruker 4–7 dager. Resten av partiet beholder du.</p><form id="saleForm"><div class="purchase-rows">${ids.map(i=>{const m=G.market(s,i),max=Math.min(s.stock[i],m.demand);return `<label><span><b>${G.GOODS[i].name}</b><small>${kr(m.price)} / stk. · etterspørsel ${m.demand} · du har ${s.stock[i]}${m.saturation?' · −'+m.saturation+' % metning':''}</small></span><input id="sellQ${i}" aria-label="Selg ${G.GOODS[i].name}" type="number" min="0" max="${max}" value="${max}" step="1"></label>`;}).join('')}</div><div class="planner-quote" id="saleQuote"></div><button class="button brass" type="submit">Gjennomfør salget →</button></form>`);const read=()=>G.GOODS.map((g,i)=>ids.includes(i)?+$('#sellQ'+i).value:0);function draw(){const q=read().map((n,i)=>G.saleQuote(s,i,n)),gross=q.reduce((n,r)=>n+r.gross,0),basis=q.reduce((n,r)=>n+r.basis,0);$('#saleQuote').innerHTML=`<div class="between"><span>Bruttosalg til kassa</span><b>${kr(gross)}</b></div><div class="between"><span>Varekostnad, allerede betalt</span><b>${debit(basis)}</b></div><div class="between estimate"><span>Varefortjeneste før reise og drift</span><b>${kr(gross-basis)}</b></div><p class="small">Fredag og lørdag gir normalt bedre priser og høyere etterspørsel. Mange salg metter markedet. Tid brukt på salg er også en kostnad.</p>`;}ids.forEach(i=>$('#sellQ'+i).oninput=draw);draw();$('#saleForm').onsubmit=e=>{e.preventDefault();const before=s.sales;act('streetSell',read());if(s.sales>before)$('#dialog').close();};}
function finance(){modal(`<span class="section-kicker">FINANS OG KONSEKVENSER</span><h2>Lån er ikkje formue.</h2><p>Netto formue: ${kr(G.netWorth(s))}. Kontanter teller, gjeld trekkes fra. Beholdning og eiendom gir ikke automatisk en høyere rang.</p>${s.loan?`<p>Gjeld ${kr(s.loan.balance)}. Forfall om ${s.loan.due-s.day} dager. Betales automatisk hvis kassa dekker det. Ellers øker saldoen 20 %, fristen forlenges 28 dager og søkelyset øker 8.</p>${btn('repay','','Gjør opp lånet',s.cash<s.loan.balance,'button brass')}`:`<p>Låneramme ${kr([10000,50000,200000,500000,1500000,3000000][s.rankLevel])}. 20 % påslag. Forfall om 28 dager.</p>${btn('borrow','','Ta opp lån',false,'button ghost')}`}<hr><h3>Advokatbistand · nivå ${s.lawyer}</h3><p>Reduserer boten hvis en ny last blir beslaglagt. Fjerner aldri tollrisikoen og gir ikke varene tilbake.</p>${btn('lawyer','',s.lawyer<3?'Oppgrader · '+kr([15000,75000,300000][s.lawyer]):'Fullt utbygd',s.lawyer>=3||s.cash<([15000,75000,300000][s.lawyer]||Infinity),'button ghost')}`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='buyAbroad'||b.id==='buyAbroadHero')countries();if(b.id==='sellStreet'||b.id==='sellStreetHero')sellMarket();if(b.dataset.country!==undefined)purchase(+b.dataset.country);if(b.id==='finance')finance();if(b.dataset.store!==undefined)act('stash',{good:+b.dataset.store,to:b.dataset.direction});});
const previousGuide=$('#guide').onclick;$('#guide').onclick=()=>modal(`<span class="section-kicker">FRA VAREHANDLER TIL GUDFAR</span><h2>Samme forsyningskjede. En ny rolle.</h2><p><b>Start:</b> 8 000 kr og ingen ansatte. Velg en tur til utlandet, kjøp et faktisk parti og få det hjem gjennom tollen. Reisekostnad og kalenderdager løper uansett. Salg er en egen handling i Stavanger.</p><p><b>Marked:</b> Pris, etterspørsel, ukedag og metning påvirker salget. Dagens tilbud kan ikke rulles på nytt ved å åpne vinduet igjen. Varekostnad følger lageret.</p><p><b>Rang:</b> Opptjent netto formue låser opp varer og forbindelser. Lån teller ikke. Gudfar krever 80 millioner i produktiv imperieverdi og et fungerende nettverk: fire byer, tre lokale maktavtaler, to institusjoner og et stort arveprosjekt. Se alle krav i Maktrådet.</p><p><b>Pusher:</b> Ved 250 000 i formue og én driftsleder åpner faste utenlandske innkjøpsruter og et salgsapparat som selger hele lageret. Ingen fast månedlig omsetningsgrense.</p><p><b>Bakmann og Gudfar:</b> Utvid produksjon, distribusjon og bynettverk. Du tar allianser, rivaler, risiko og kapitalvalg. Folkene tar vareflyten.</p><p><b>Rolig dag:</b> −2 søkelys og −2 slitasje. Ei rolig uke gir −18 søkelys før aktive ruter og −12 slitasje. Drift fortsetter.</p><p class="small">Spillbar alfa 0.8. Tidligere testlagringer bevares; start gjerne en ny runde for den nye progresjonen. </p><details><summary>Om Vestkyst</summary><p>Personer, selskaper og kriminalhistorier er fiksjon. Festivalnavnene er virkelige; spillkalenderen bruker modellerte festivalvinduer som ikke er offisielle datoer for fremtidige år. Priser og reisetider er spillregler. Rivalene er datastyrte.</p></details>`);
render();
